for cid, d in P.items():
    obj = {
        "case_id": cid,
        "prediction_text": d["text"],
        "basis": d["basis"],
        "confidence": d["conf"],
        "trigger": dict(TRIG),
    }
    with open(os.path.join(OUT, cid + ".json"), "w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=1)

print("written", len(P))
for cid in P:
    p = os.path.join(OUT, cid + ".json")
    o = json.load(open(p, encoding="utf-8"))
    assert o["case_id"] == cid and o["prediction_text"] and o["basis"]
    assert set(o["trigger"].keys()) == {"changed_main", "reserve_used", "disputed", "reason"}
    print(cid, "ok", o["confidence"])
